import React, { useEffect, useState } from 'react'
import Typography from '../Typography/Typography'
import { AriaLiveRole } from '../utilities/aria'
import Progress from './Progress'

export default {
  title: 'Components/Progress',
  component: Progress,
}

export function Determinate(): JSX.Element {
  const [circularProgress, setCircularProgress] = useState(0)
  const [linearProgress, setLinearProgress] = useState(0)

  useEffect(() => {
    const timer = setInterval(() => {
      setCircularProgress((prevProgress) =>
        prevProgress >= 100 ? 0 : prevProgress + 10,
      )
    }, 800)

    return () => {
      clearInterval(timer)
    }
  }, [])

  useEffect(() => {
    const timer = setInterval(() => {
      setLinearProgress((oldProgress) => {
        if (oldProgress === 100) {
          return 0
        }

        const diff = Math.random() * 10

        return Math.min(oldProgress + diff, 100)
      })

      return () => {
        clearInterval(timer)
      }
    }, 500)
  }, [])

  return (
    <div className="flex flex-col space-y-8">
      <div className="flex flex-col space-y-8">
        <div className="space-y-4">
          <Progress aria-valuetext="0 out of 4" value={0} />
          <Progress aria-valuetext="1 out of 4" value={25} />
          <Progress aria-valuetext="2 out of 4" value={50} />
          <Progress aria-valuetext="3 out of 4" value={75} />
          <Progress aria-valuetext="4 out of 4" value={100} />
          <Progress
            aria-valuetext={`${Math.floor(
              (linearProgress / 100) * 4,
            )} out of 4`}
            value={linearProgress}
          />
        </div>

        <div className="space-y-4">
          <Progress aria-valuetext="0 out of 4" color="secondary" value={0} />
          <Progress aria-valuetext="1 out of 4" color="secondary" value={25} />
          <Progress aria-valuetext="2 out of 4" color="secondary" value={50} />
          <Progress aria-valuetext="3 out of 4" color="secondary" value={75} />
          <Progress aria-valuetext="4 out of 4" color="secondary" value={100} />
          <Progress
            aria-valuetext={`${Math.floor(
              (linearProgress / 100) * 4,
            )} out of 4`}
            color="secondary"
            value={linearProgress}
          />
        </div>
      </div>

      <div className="flex flex-col space-y-8">
        <div className="flex flex-row justify-between">
          <Progress aria-valuetext="0 out of 4" value={0} variant="circular" />
          <Progress aria-valuetext="1 out of 4" value={25} variant="circular" />
          <Progress aria-valuetext="2 out of 4" value={50} variant="circular" />
          <Progress aria-valuetext="3 out of 4" value={75} variant="circular" />
          <Progress
            aria-valuetext="4 out of 4"
            value={100}
            variant="circular"
          />
          <Progress
            aria-valuetext={`${Math.floor(
              (circularProgress / 100) * 4,
            )} out of 4`}
            value={circularProgress}
            variant="circular"
          />
        </div>

        <div className="flex flex-row justify-between">
          <Progress
            aria-valuetext="0 out of 4"
            color="secondary"
            value={0}
            variant="circular"
          />
          <Progress
            aria-valuetext="1 out of 4"
            color="secondary"
            value={25}
            variant="circular"
          />
          <Progress
            aria-valuetext="2 out of 4"
            color="secondary"
            value={50}
            variant="circular"
          />
          <Progress
            aria-valuetext="3 out of 4"
            color="secondary"
            value={75}
            variant="circular"
          />
          <Progress
            aria-valuetext="4 out of 4"
            color="secondary"
            value={100}
            variant="circular"
          />
          <Progress
            aria-valuetext={`${Math.floor(
              (circularProgress / 100) * 4,
            )} out of 4`}
            color="secondary"
            value={circularProgress}
            variant="circular"
          />
        </div>

        <div className="flex flex-row justify-between">
          <Progress
            aria-valuetext="0 out of 4"
            size="medium"
            value={0}
            variant="circular"
          />
          <Progress
            aria-valuetext="1 out of 4"
            size="medium"
            value={25}
            variant="circular"
          />
          <Progress
            aria-valuetext="2 out of 4"
            size="medium"
            value={50}
            variant="circular"
          />
          <Progress
            aria-valuetext="3 out of 4"
            size="medium"
            value={75}
            variant="circular"
          />
          <Progress
            aria-valuetext="4 out of 4"
            size="medium"
            value={100}
            variant="circular"
          />
          <Progress
            aria-valuetext={`${Math.floor(
              (circularProgress / 100) * 4,
            )} out of 4`}
            size="medium"
            value={circularProgress}
            variant="circular"
          />
        </div>

        <div className="flex flex-row justify-between">
          <Progress
            aria-valuetext="0 out of 4"
            size="small"
            value={0}
            variant="circular"
          />
          <Progress
            aria-valuetext="1 out of 4"
            size="small"
            value={25}
            variant="circular"
          />
          <Progress
            aria-valuetext="2 out of 4"
            size="small"
            value={50}
            variant="circular"
          />
          <Progress
            aria-valuetext="3 out of 4"
            size="small"
            value={75}
            variant="circular"
          />
          <Progress
            aria-valuetext="4 out of 4"
            size="small"
            value={100}
            variant="circular"
          />
          <Progress
            aria-valuetext={`${Math.floor(
              (circularProgress / 100) * 4,
            )} out of 4`}
            size="small"
            value={circularProgress}
            variant="circular"
          />
        </div>
      </div>

      <Typography>
        Test the progressbars with assistive technology to see value description
      </Typography>
    </div>
  )
}

export function Indeterminate(): JSX.Element {
  return (
    <div className="flex flex-col space-y-8">
      <Progress />
      <Progress color="secondary" />
      <Progress variant="circular" />
      <Progress color="secondary" variant="circular" />
    </div>
  )
}

